public class AnnotationCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("countMarked(Subject.class)", 3, AnnotationCounter.countMarked(Subject.class));
        check("countMarked(Plain.class) -- nothing annotated", 0, AnnotationCounter.countMarked(Plain.class));
        check("countMarked(Solo.class)", 1, AnnotationCounter.countMarked(Solo.class));
        check("countMarked(Heavy.class)", 2, AnnotationCounter.countMarked(Heavy.class));
        check("countMarked(AnnotationCounter.class)", 0, AnnotationCounter.countMarked(AnnotationCounter.class));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

