public class AnnotationCounter {

    public static int countMarked(Class<?> c) {
        int count = 0;
        for (java.lang.reflect.Method m : c.getDeclaredMethods()) {
            if (m.isAnnotationPresent(Marked.class)) {
                count++;
            }
        }
        return count;
    }
}
